using ProjectTask.BUS; using ProjectTask.DAL; using ProjectTask.DTO; using System.Data;
namespace ProjectTask.GUI;
public class MainForm:Form {
 readonly ProjectService ps=new();readonly MemberService ms=new();readonly TaskService ts=new();
 readonly TabControl tabs=new(){Dock=DockStyle.Fill};readonly DataGridView gp=Grid(),gm=Grid(),gt=Grid(),go=Grid(),gs=Grid();
 readonly ComboBox projectFilter=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=190};readonly ComboBox statusFilter=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=140};
 readonly FlowLayoutPanel kanbanTodo=new(){Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true},kanbanProgress=new(){Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true},kanbanReview=new(){Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true},kanbanDone=new(){Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true};
 List<Project> projects=new();List<Member> members=new();List<TaskItem> tasks=new();
 static DataGridView Grid()=>new(){Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false};
 static Control KanbanColumn(string title,FlowLayoutPanel body){var g=new GroupBox{Text=title,Dock=DockStyle.Fill,Padding=new Padding(8)};g.Controls.Add(body);return g;}
 public MainForm(){Text="PROJECT & TASK MANAGEMENT - BAI TAP 6.3";Width=1250;Height=760;StartPosition=FormStartPosition.CenterScreen;Controls.Add(tabs);tabs.TabPages.Add(BuildTaskTab());tabs.TabPages.Add(BuildProjectTab());tabs.TabPages.Add(BuildMemberTab());tabs.TabPages.Add(BuildReportTab());Shown+=async(_,_)=>await Safe(LoadAll);}
 TabPage BuildTaskTab(){var p=new TabPage("Công việc / Kanban & List");var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=48,Padding=new Padding(5)};projectFilter.Width=200;statusFilter.Items.AddRange(new object[]{"Tất cả","To Do","In Progress","Review","Done"});statusFilter.SelectedIndex=0;var b=new Button{Text="Lọc",Width=75};b.Click+=async(_,_)=>await Safe(LoadTasks);var add=new Button{Text="Thêm task",Width=95};add.Click+=async(_,_)=>await Safe(()=>EditTask(false));var edit=new Button{Text="Sửa task",Width=90};edit.Click+=async(_,_)=>await Safe(()=>EditTask(true));var del=new Button{Text="Xóa task",Width=90};del.Click+=async(_,_)=>await Safe(DeleteTask);var assign=new Button{Text="Phân công",Width=90};assign.Click+=async(_,_)=>await Safe(AssignTask);var status=new Button{Text="Chuyển trạng thái",Width=125};status.Click+=async(_,_)=>await Safe(ChangeStatus);var refresh=new Button{Text="Tải lại",Width=75};refresh.Click+=async(_,_)=>await Safe(LoadTasks);bar.Controls.AddRange(new Control[]{new Label{Text="Dự án:",AutoSize=true,Padding=new Padding(0,8,0,0)},projectFilter,new Label{Text="Trạng thái:",AutoSize=true,Padding=new Padding(0,8,0,0)},statusFilter,b,add,edit,del,assign,status,refresh});var views=new TabControl{Dock=DockStyle.Fill};var listPage=new TabPage("List View");listPage.Controls.Add(gt);var kanbanPage=new TabPage("Kanban View");var board=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=4,RowCount=1};for(int i=0;i<4;i++)board.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,25));board.Controls.Add(KanbanColumn("TO DO",kanbanTodo),0,0);board.Controls.Add(KanbanColumn("IN PROGRESS",kanbanProgress),1,0);board.Controls.Add(KanbanColumn("REVIEW",kanbanReview),2,0);board.Controls.Add(KanbanColumn("DONE",kanbanDone),3,0);kanbanPage.Controls.Add(board);views.TabPages.Add(listPage);views.TabPages.Add(kanbanPage);p.Controls.Add(views);p.Controls.Add(bar);return p;}
 TabPage BuildProjectTab(){var p=new TabPage("Dự án");var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=45,Padding=new Padding(5)};var a=new Button{Text="Thêm dự án",Width=100};a.Click+=async(_,_)=>await Safe(()=>EditProject(false));var e=new Button{Text="Sửa dự án",Width=100};e.Click+=async(_,_)=>await Safe(()=>EditProject(true));var d=new Button{Text="Xóa dự án",Width=100};d.Click+=async(_,_)=>await Safe(DeleteProject);var r=new Button{Text="Tải lại",Width=80};r.Click+=async(_,_)=>await Safe(LoadAll);bar.Controls.AddRange(new Control[]{a,e,d,r});p.Controls.Add(gp);p.Controls.Add(bar);return p;}
 TabPage BuildMemberTab(){var p=new TabPage("Thành viên");p.Controls.Add(gm);return p;}
 TabPage BuildReportTab(){var p=new TabPage("Báo cáo & quá hạn");var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=45,Padding=new Padding(5)};var o=new Button{Text="Công việc quá hạn",Width=150};o.Click+=async(_,_)=>await Safe(async()=>go.DataSource=await ts.GetOverdueAsync());var s=new Button{Text="Tỷ lệ hoàn thành",Width=150};s.Click+=async(_,_)=>await Safe(async()=>gs.DataSource=await ts.GetStatsAsync(SelectedProjectId()));bar.Controls.AddRange(new Control[]{o,s,new Label{Text="Bảng trên: quá hạn | Bảng dưới: tiến độ theo thành viên",AutoSize=true,Padding=new Padding(5,8,0,0)}});var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,SplitterDistance=260};split.Panel1.Controls.Add(go);split.Panel2.Controls.Add(gs);p.Controls.Add(split);p.Controls.Add(bar);return p;}
 int SelectedProjectId()=>projectFilter.SelectedItem is Project x?x.MaDuAn:0;
 async Task LoadAll(){await Db.TestConnectionAsync();projects=await ps.GetAllAsync();members=await ms.GetAllAsync();gp.DataSource=projects;gm.DataSource=members;projectFilter.Items.Clear();projectFilter.Items.Add("Tất cả");foreach(var x in projects)projectFilter.Items.Add(x);projectFilter.DisplayMember="TenDuAn";projectFilter.SelectedIndex=0;await LoadTasks();Text="PROJECT & TASK MANAGEMENT - Đã kết nối ProjectTaskDB";}
 async Task LoadTasks(){int pid=SelectedProjectId();string st=statusFilter.SelectedItem?.ToString()??"Tất cả";tasks=await ts.GetAllAsync(pid,st=="Tất cả"?"":st);gt.DataSource=null;gt.DataSource=tasks;kanbanTodo.Controls.Clear();kanbanProgress.Controls.Clear();kanbanReview.Controls.Clear();kanbanDone.Controls.Clear();foreach(var t in tasks){var card=new Label{AutoSize=false,Width=245,Height=92,BorderStyle=BorderStyle.FixedSingle,Padding=new Padding(8),Margin=new Padding(5),Text=$"{t.TenTask}\nDự án: {t.TenDuAn}\nƯu tiên: {t.DoUuTien}\nHạn: {(t.HanNop.HasValue?t.HanNop.Value.ToString("dd/MM/yyyy"):"Chưa đặt")}"};var target=t.TrangThai switch{"In Progress"=>kanbanProgress,"Review"=>kanbanReview,"Done"=>kanbanDone,_=>kanbanTodo};target.Controls.Add(card);}}
 async Task EditProject(bool edit){Project? old=edit?gp.CurrentRow?.DataBoundItem as Project:null;if(edit&&old==null)throw new Exception("Chọn dự án cần sửa.");using var f=new Form{Text=edit?"Sửa dự án":"Thêm dự án",Width=430,Height=330,StartPosition=FormStartPosition.CenterParent};var name=Field(f,"Tên dự án",old?.TenDuAn??"",20,20);var start=DateField(f,"Ngày bắt đầu",old?.NgayBatDau,20,75);var end=DateField(f,"Ngày kết thúc",old?.NgayKetThuc,20,130);var state=Combo(f,"Trạng thái",new[]{"Đang chạy","Hoàn thành","Tạm dừng"},old?.TrangThai??"Đang chạy",20,185);var ok=Ok(f);ok.Click+=async(_,_)=>{try{await ps.SaveAsync(new Project{MaDuAn=old?.MaDuAn??0,TenDuAn=name.Text.Trim(),NgayBatDau=start.Checked?start.Value:null,NgayKetThuc=end.Checked?end.Value:null,TrangThai=state.Text},!edit);f.DialogResult=DialogResult.OK;f.Close();}catch(Exception ex){MessageBox.Show(ex.Message);}};if(f.ShowDialog(this)==DialogResult.OK)await LoadAll();}
 async Task EditTask(bool edit){TaskItem? old=edit?gt.CurrentRow?.DataBoundItem as TaskItem:null;if(edit&&old==null)throw new Exception("Chọn task cần sửa.");using var f=new Form{Text=edit?"Sửa công việc":"Thêm công việc",Width=500,Height=470,StartPosition=FormStartPosition.CenterParent};var pr=ComboProject(f,old?.MaDuAn??(projects.FirstOrDefault()?.MaDuAn??0));var name=Field(f,"Tên công việc",old?.TenTask??"",20,75);var desc=Field(f,"Mô tả",old?.MoTa??"",20,130);var due=DateField(f,"Hạn nộp",old?.HanNop,20,185);var priority=Combo(f,"Ưu tiên",new[]{"Cao","Trung bình","Thấp"},old?.DoUuTien??"Trung bình",20,240);var state=Combo(f,"Trạng thái",new[]{"To Do","In Progress","Review","Done"},old?.TrangThai??"To Do",20,295);var ok=Ok(f);ok.Top=365;ok.Click+=async(_,_)=>{try{await ts.SaveAsync(new TaskItem{MaTask=old?.MaTask??0,MaDuAn=pr.SelectedItem is Project x?x.MaDuAn:0,TenTask=name.Text.Trim(),MoTa=desc.Text,HanNop=due.Checked?due.Value:null,DoUuTien=priority.Text,TrangThai=state.Text},!edit);f.DialogResult=DialogResult.OK;f.Close();}catch(Exception ex){MessageBox.Show(ex.Message);}};if(f.ShowDialog(this)==DialogResult.OK)await LoadTasks();}
 async Task DeleteTask(){if(gt.CurrentRow?.DataBoundItem is not TaskItem t)throw new Exception("Chọn công việc.");if(MessageBox.Show("Xóa công việc đã chọn?","Xác nhận",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;await ts.DeleteAsync(t.MaTask);await LoadTasks();}
 async Task DeleteProject(){if(gp.CurrentRow?.DataBoundItem is not Project p)throw new Exception("Chọn dự án.");if(MessageBox.Show("Xóa dự án và các task liên quan?","Xác nhận",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;await ps.DeleteAsync(p.MaDuAn);await LoadAll();}
 async Task AssignTask(){if(gt.CurrentRow?.DataBoundItem is not TaskItem t)throw new Exception("Chọn task cần phân công.");if(members.Count==0)throw new Exception("Chưa có thành viên trong CSDL.");using var f=new Form{Text="Phân công công việc",Width=380,Height=180,StartPosition=FormStartPosition.CenterParent};var cb=new ComboBox{Left=20,Top=25,Width=320,DropDownStyle=ComboBoxStyle.DropDownList,DataSource=members,DisplayMember="HoTen"};f.Controls.Add(cb);var b=Ok(f);b.Top=75;b.Click+=async(_,_)=>{if(cb.SelectedItem is Member m){await ts.AssignAsync(t.MaTask,m.MaThanhVien);f.DialogResult=DialogResult.OK;f.Close();}};if(f.ShowDialog(this)==DialogResult.OK)await LoadTasks();}
 async Task ChangeStatus(){if(gt.CurrentRow?.DataBoundItem is not TaskItem t)throw new Exception("Chọn task.");using var f=new Form{Text="Chuyển trạng thái",Width=330,Height=160,StartPosition=FormStartPosition.CenterParent};var cb=new ComboBox{Left=20,Top=20,Width=270,DropDownStyle=ComboBoxStyle.DropDownList};cb.Items.AddRange(new object[]{"To Do","In Progress","Review","Done"});cb.SelectedItem=t.TrangThai;f.Controls.Add(cb);var b=Ok(f);b.Top=65;b.Click+=async(_,_)=>{await ts.UpdateStatusAsync(t.MaTask,cb.Text);f.DialogResult=DialogResult.OK;f.Close();};if(f.ShowDialog(this)==DialogResult.OK)await LoadTasks();}
 async Task Safe(Func<Task> a){try{await a();}catch(Exception ex){MessageBox.Show(ex.Message,"Thông báo",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
 static TextBox Field(Form f,string label,string value,int x,int y){f.Controls.Add(new Label{Text=label,Left=x,Top=y+5,Width=110});var t=new TextBox{Left=x+120,Top=y,Width=320,Text=value};f.Controls.Add(t);return t;}
 static DateTimePicker DateField(Form f,string label,DateTime? value,int x,int y){f.Controls.Add(new Label{Text=label,Left=x,Top=y+5,Width=110});var d=new DateTimePicker{Left=x+120,Top=y,Width=220,Format=DateTimePickerFormat.Short,ShowCheckBox=true,Checked=value.HasValue};if(value.HasValue)d.Value=value.Value;f.Controls.Add(d);return d;}
 static ComboBox Combo(Form f,string label,string[] values,string selected,int x,int y){f.Controls.Add(new Label{Text=label,Left=x,Top=y+5,Width=110});var c=new ComboBox{Left=x+120,Top=y,Width=220,DropDownStyle=ComboBoxStyle.DropDownList};c.Items.AddRange(values);c.SelectedItem=selected;f.Controls.Add(c);return c;}
 ComboBox ComboProject(Form f,int id){f.Controls.Add(new Label{Text="Dự án",Left=20,Top=30,Width=110});var c=new ComboBox{Left=140,Top=25,Width=300,DropDownStyle=ComboBoxStyle.DropDownList,DataSource=projects.ToList(),DisplayMember="TenDuAn"};c.SelectedItem=projects.FirstOrDefault(x=>x.MaDuAn==id);f.Controls.Add(c);return c;}
 static Button Ok(Form f){var b=new Button{Text="Lưu",Left=140,Top=250,Width=100,DialogResult=DialogResult.None};f.Controls.Add(b);f.AcceptButton=b;return b;}
}
